mapper.sql:
WHERE (d.owner_id = HEXTORAW(#{ownerId})
OR EXISTS ( SELECT 1 FROM edudoc_collab_member m JOIN edudoc_collab_session s ON s.id = m.collab_session_id WHERE s.document_id = d.id AND m.user_id = HEXTORAW(#{ownerId}) AND m.connection_status != 'REMOVED' )
)
AND d.status = #{status} AND d.status != 'DELETED'
AND d.course_id = HEXTORAW(#{courseId}) AND d.doc_type = #{docType}
AND UPPER(d.title) LIKE '%' || UPPER(#{keyword}) || '%' ESCAPE '\'
